#include "elit21/shopify/webhooks/ShopifyWebhookHandlerSupport.h"
#include <algorithm>
namespace elit21::shopify::webhooks {Result<void>persistWebhookTask(Database&db,const ShopifyWebhook&e,std::initializer_list<ShopifyWebhookTopic>accepted,int priority){if(std::find(accepted.begin(),accepted.end(),e.topic())==accepted.end())return Result<void>::failure("Webhook topic rejected by domain handler");auto valid=e.validate();if(!valid)return valid;Json p=Json::object();p.set("webhook_id",e.id());p.set("topic",topicName(e.topic()));p.set("shop_domain",e.shopDomain());p.set("api_version",e.apiVersion());p.set("payload_hash",e.payloadHash());p.set("payload",e.body());auto queued=db.enqueueUniqueTask(taskKind(e.topic()),p.dump(),priority,{},e.dedupeKey());if(!queued)return Result<void>::failure(queued.error());db.audit("INFO","shopify_webhook_handler","Webhook task persisted",p.dump(),e.id());return Result<void>::success();}}
